from lib import *
S = SS('j250')
steps = [
    step("线程的身份取决于谁创建它:main 线程里 new Thread 是 Thread-0(daemon=false, prio=5);在 daemon 线程里 new Thread 得到 daemon=true;在优先级 9 的线程里 new Thread 得到 prio=9——都继承了创建者。而在 daemon 线程里用 Executors.defaultThreadFactory() 创建的线程是 pool-1-thread-1(daemon=false, prio=5),不继承。固定线程池 2 个线程的默认名字是 pool-2-thread-1 与 pool-2-thread-2,线程组 main。", t=tl(S(1)), done=lidx(S(1), 'main 线程里 new Thread', '在 daemon 线程里 new Thread'), mark=lidx(S(1), '在优先级 9 的线程里 new Thread', '固定线程池 2 个线程的默认名字'), kv=KV([['new Thread', '继承创建者的 daemon 与优先级'], ['defaultThreadFactory', '总是 daemon=false、prio=5'], ['默认命名', 'pool-N-thread-M']], ['defaultThreadFactory'])),
    step("未捕获异常:submit() 里抛出的异常不会到达 UncaughtExceptionHandler,而是封装在 Future 里(Future.get() 抛 ExecutionException),worker-1 继续运行下一个任务;execute() 里抛出的异常会到达 handler(“线程 worker-1,异常 execute 里的异常”),这个线程随即终止,池新建了 worker-2 去执行之后的任务,ThreadFactory 一共创建了 2 个线程。线程名字在替换后变了,按线程名统计的日志与监控要考虑到这一点。", t=tl(S(2)), done=lidx(S(2), 'submit:handler 没有被调用', '第二个任务在 worker-1'), mark=lidx(S(2), 'handler 收到:线程 worker-1', '在 worker-2 上运行', 'ThreadFactory 一共创建了 2 个线程'), kv=KV([['submit 抛异常', 'handler 不调用;Future.get() 抛 ExecutionException'], ['execute 抛异常', 'handler 收到;线程死亡;池换成 worker-2']], ['execute 抛异常'])),
    step("线程池里的线程在创建时“拍下”创建者的上下文:池由 main 线程创建,但第一次提交来自 submitter 线程(它的 context ClassLoader 是 custom-loader,InheritableThreadLocal 是 submitter-的值)。于是池线程的 context ClassLoader = custom-loader、InheritableThreadLocal = submitter-的值;而 main 线程自己的是 AppClassLoader(app)与 main-的值。main 再提交任务也不会更新池线程已有的这两个值——谁第一次触发创建,谁的上下文就留在线程里。", t=tl(S(3)), done=lidx(S(3), '池线程(由 submitter 线程第一次提交时创建)'), mark=lidx(S(3), 'main 线程现在的 context ClassLoader'), kv=KV([['池线程(由 submitter 触发创建)', 'custom-loader / submitter-的值'], ['main 线程', 'AppClassLoader / main-的值']], ['池线程(由 submitter 触发创建)'])),
    step("daemon 决定 JVM 能不能退出:main 结束后线程池没有 shutdown。默认的非 daemon 线程:输出 “main 结束” 之后 5 秒 JVM 仍未退出(被杀掉);用 setDaemon(true) 的 ThreadFactory:JVM 在 0.1 s 内退出,退出码 0。这两种都不是好做法:前者会让进程挂住,后者会在退出时直接丢掉还没完成的任务;正确的是在退出路径上 shutdown 并等待。", t=tl(S(4)), done=lidx(S(4), 'exit-nondaemon'), mark=lidx(S(4), 'exit-daemon'), kv=KV([['非 daemon 线程池不 shutdown', '5 秒后 JVM 仍未退出'], ['daemon 线程池不 shutdown', '0.1 s 内退出,未完成任务被丢弃']], ['非 daemon 线程池不 shutdown'])),
    step("线程是惰性创建的:new ThreadPoolExecutor(2, 4, 队列 2) 构造后 ThreadFactory 调用 0 次。连续提交 6 个阻塞任务,调用次数依次是 1、2、2、2、3、4:前 2 个任务创建核心线程,第 3、4 个进队列,队列满后第 5、6 个才创建到最大线程数 4。任务结束 500 ms 后(keepAlive 100 ms)池大小仍是 2(核心线程默认不回收),allowCoreThreadTimeOut(true) 再等 500 ms 后池大小 0。虚拟线程的 ThreadFactory 生成 vt-0、vt-1,isDaemon() = true,setPriority(10) 之后 getPriority() 仍是 5,setDaemon(false) 抛 IllegalArgumentException。", t=tl(S(5)), done=lidx(S(5), '构造后 ThreadFactory 调用 0 次', '连续提交 6 个阻塞任务'), mark=lidx(S(5), '任务结束 500 ms 后', 'allowCoreThreadTimeOut(true) 后再等 500 ms', '虚拟线程'), b=bars([['构造后', 0, '0'], ['2 个任务后', 2, '2'], ['4 个任务后', 2, '2'], ['5 个任务后', 3, '3'], ['6 个任务后', 4, '4']], 4, done=[0, 1, 2, 3, 4]), kv=KV([['核心线程 2 + 队列 2 + 最大 4', '第 1、2、5、6 个任务各创建 1 个线程'], ['虚拟线程', 'daemon 固定为 true,优先级固定为 5']], ['核心线程 2 + 队列 2 + 最大 4'])),
]
A = mkartj('j250', 250, 'Java,并发,ThreadFactory,线程池,UncaughtExceptionHandler,daemon,真实验证,动画演示',
    '在 JDK 21 上实测 ThreadFactory 决定的线程身份:new Thread 继承创建者的 daemon / 优先级而 defaultThreadFactory 不继承;submit 抛异常不进入 UncaughtExceptionHandler,execute 抛异常会换线程;池线程拍下首次提交者的 context ClassLoader 与 InheritableThreadLocal;非 daemon 池让 JVM 5 秒不退出;线程是惰性创建的(0 → 1 → 2 → 2 → 2 → 3 → 4)。',
    '线程池里每个线程的名字、daemon、异常处理和上下文,都是由 ThreadFactory 与线程第一次被创建时的环境决定的。这篇逐项量出:哪些属性继承、哪些不继承,异常去哪了,上下文是什么时候被固定的,以及线程什么时候才真正创建。',
    [('0.1 s vs 5 s+', 'main 结束后没有 shutdown 的线程池:daemon 线程池让 JVM 退出的用时 vs 非 daemon 线程池(5 秒后仍未退出)'), ('custom-loader', '由 submitter 线程第一次提交时创建的池线程的 context ClassLoader(main 线程自己是 AppClassLoader)'), ('1, 2, 2, 2, 3, 4', 'ThreadPoolExecutor(2, 4, 队列 2) 连续提交 6 个任务后,ThreadFactory 的累计调用次数')],
    [('线程身份与继承', None), ('未捕获异常', None), ('创建时拍下的上下文', None), ('daemon 与 JVM 退出', None), ('惰性创建与虚拟线程', None)],
    steps, [ENV_J + '。JDK 21.0.12;自写的 ThreadFactory 与最小任务', '没有验证:Spring ThreadPoolTaskExecutor / Tomcat 线程池的命名与上下文传播、TransmittableThreadLocal 等传播方案、结构化并发(StructuredTaskScope)的线程上下文、SecurityManager / 访问控制上下文的继承(JDK 21 已弃用)'], 'ThreadFactory')
